let sum_list xs =
  let rec go acc = function
    | [] -> acc
    | x :: rest -> go (acc + x) rest
  in
  go 0 xs

let rev xs =
  let rec go acc = function [] -> acc | x :: rest -> go (x :: acc) rest in
  go [] xs

