let compose f g = fun x -> f (g x)

let () =
  let add10 = make_adder 10 in
  let evens = List.filter (fun n -> n mod 2 = 0) [1; 2; 3; 4; 5; 6] in
  List.iter (Printf.printf "%d ") (List.map add10 evens);
  print_newline ();
